CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE tenants(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, plan text NOT NULL DEFAULT 'PRO', status text NOT NULL DEFAULT 'TRIAL', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE branches(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants(id) ON DELETE CASCADE, name text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE users(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants(id) ON DELETE CASCADE, name text NOT NULL, email text NOT NULL, password_hash text NOT NULL, role text NOT NULL DEFAULT 'CAIXA', active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(tenant_id,email));
CREATE TABLE products(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants(id) ON DELETE CASCADE, sku text NOT NULL, barcode text, name text NOT NULL, price numeric(14,2) NOT NULL DEFAULT 0, cost numeric(14,2) NOT NULL DEFAULT 0, stock numeric(14,3) NOT NULL DEFAULT 0, min_stock numeric(14,3) NOT NULL DEFAULT 0, active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(tenant_id,sku));
CREATE TABLE sales(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants(id) ON DELETE CASCADE, branch_id uuid NOT NULL REFERENCES branches(id), user_id uuid NOT NULL REFERENCES users(id), total numeric(14,2) NOT NULL, payment_method text NOT NULL, status text NOT NULL DEFAULT 'COMPLETED', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE sale_items(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), sale_id uuid NOT NULL REFERENCES sales(id) ON DELETE CASCADE, product_id uuid NOT NULL REFERENCES products(id), qty numeric(14,3) NOT NULL, unit_price numeric(14,2) NOT NULL, unit_cost numeric(14,2) NOT NULL DEFAULT 0);
CREATE TABLE inventory_movements(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants(id) ON DELETE CASCADE, branch_id uuid NOT NULL REFERENCES branches(id), product_id uuid NOT NULL REFERENCES products(id), user_id uuid REFERENCES users(id), kind text NOT NULL, qty numeric(14,3) NOT NULL, reference_id uuid, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE audit_logs(id bigserial PRIMARY KEY, tenant_id uuid, user_id uuid, action text NOT NULL, metadata jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX idx_products_tenant ON products(tenant_id); CREATE INDEX idx_sales_tenant_date ON sales(tenant_id,created_at); CREATE INDEX idx_inventory_tenant_product ON inventory_movements(tenant_id,product_id);
